#!/bin/bash\n\n# Self-validity check: Ensure necessary tools are available.\ncommand -v find >/dev/null 2>&1 || { echo \"VALIDITY FAILURE: \'find\' command not found.\"; exit 2; }\ncommand -v grep >/dev/null 2>&1 || { echo \"VALIDITY FAILURE: \'grep\' command not found.\"; exit 2; }\ncommand -v bash >/dev/null 2>&1 || { echo \"VALIDITY FAILURE: \'bash\' command not found.\"; exit 2; }\n\necho \"Running Forbidden Infrastructure Tests...\"\n\n# Test 1: Verify absence of new executable runtime infrastructure for artifact management.\n# This is a heuristic test looking for common patterns of executable scripts in unexpected places.\n# Forbidden infrastructure might include standalone scripts for artifact generation/management,\n# new runtime configurations not part of AEF or project standards.\n\necho \"Searching for potential forbidden executable infrastructure...\"\n\nfound_forbidden_infra=false\n\n# Construct the find command with correct syntax for primaries.\n# Exclude known directories and file types that are typically allowed.\n# The goal is to catch unintended artifact management scripts.\n\n# Use find to locate executable files. Exclude known safe directories/patterns.\n# The corrected syntax uses -executable as a primary, and multiple -path conditions combined with -o (OR) and \! (NOT).\n\n# Define exclusion patterns for directories and file types that are generally allowed.\nEXCLUDE_PATTERNS=(\n    \"./tests/*\"\n    \"./scripts/*\"\n    \"./skills/*\"\n    \"./src/*\"\n    \"./lib/*\"\n    \"./.omp/*\"\n    \"./node_modules/*\"\n    \"*.py\" # Assuming python files might be common and not inherently forbidden\n)\n\nFIND_CMD=\"find . -type f -executable\"\n\n# Add exclusions to the find command.\nfor pattern in \"${EXCLUDE_PATTERNS[@]}\"; do\n    FIND_CMD=\"$FIND_CMD ! -path \\\"$pattern\\\"\"\ndone\n\n# Add a specific check for files that *do* match forbidden criteria within the allowed paths.\n# This part is tricky as 'forbidden' is broad. We look for executable files with names suggesting artifact management.\n# Let's refine the search to look for executable files with specific keywords in their names, excluding the explicitly excluded paths.\n\necho \"Checking for executable files with suspicious names...\"\n\n# Find executable files, then pipe to grep for suspicious names, ensuring exclusions are handled.\n# Note: The pipeline approach with find ... -print0 | xargs -0 grep ... is generally more robust.\n# However, to keep it within a single bash command for simplicity, we'll try to integrate the check.\n\n# Find executable files and then filter them by name/content.\n# We want to find executable files that are NOT in excluded paths and have names suggesting forbidden infra.\n\n# Using -print0 and xargs -0 for safe handling of filenames with spaces or special characters.\n# We'll pipe the results of find (which already excludes paths via ! -path) to grep for suspicious names.\n# The suspicious names are heuristic, looking for keywords like 'artifact', 'id', 'metadata', 'generate', 'validate', 'manage', 'convention', 'standard'.\n\nif eval \"$FIND_CMD -print0\" | xargs -0 -r grep -Ei --color=never \"(artifact|id|metadata|generate|validate|manage|convention|standard)\" && [ $? -eq 0 ]; then\n    # If grep finds matches (exit code 0), it means forbidden infrastructure might exist.\n    # We need to process this to ensure the files found are truly executable and not in excluded paths.\n    # The previous find command already tried to handle exclusions, but this grep might catch things.\n    # Re-run find and grep together to be more precise.\n    if eval \"$FIND_CMD -print0\" | xargs -0 -r grep -Ei --color=never \"(artifact|id|metadata|generate|validate|manage|convention|standard)\"; then\n        echo \"FAIL: Potential forbidden executable infrastructure found. (See above for specific files).\"\n        found_forbidden_infra=true\n    fi\nfi\n\n# Check for runtime configuration files that might imply new infrastructure.\n# Example: new config files for non-standard services or tools.\n\necho \"Searching for potential forbidden runtime configurations...\"\n\nCONFIG_EXCLUDE_PATTERNS=(\n    \"./tests/*\"\n    \"./scripts/*\"\n    \"./skills/*\"\n    \"./src/*\"\n    \"./lib/*\"\n    \"./.omp/*\"\n    \"./node_modules/*\"\n)\n\nCONFIG_FIND_CMD=\"find . -type f \\( -name \\\"*.config.js\\\" -o -name \\\"*.runtime.js\\\" -o -name \\\"*artifact*.js\\\" -o -name \\\"*artifact*.py\\\" \\)\"\n\nfor pattern in \"${CONFIG_EXCLUDE_PATTERNS[@]}\"; do\n    CONFIG_FIND_CMD=\"$CONFIG_FIND_CMD ! -path \\\"$pattern\\\"\"\ndone\n\nif eval \"$CONFIG_FIND_CMD -print0\" | xargs -0 -r grep -qiE \"artifact|manager|runtime|config\"; then\n    echo \"FAIL: Potential forbidden runtime configuration found.\"\n    echo \"    Reason: Configuration file suggesting unauthorized runtime infrastructure.\"\n    found_forbidden_infra=true\nfi\n\n\nif [ \"$found_forbidden_infra\" = true ]; then\n    exit 1\nelse\n    echo \"No obvious forbidden executable infrastructure or runtime configurations found.\"\n    exit 0\nfi\n